import 'package:flutter/foundation.dart';
import 'package:flutter/widgets.dart';

/// A brand's own typed tokens (ADR-32), usually generated by `camo theme import`.
/// Read with `CamoTheme.tokens`; [lerp] lets animated theme switches blend it.
abstract class CamoTokenSet<T extends CamoTokenSet<T>> {
  /// Const constructor for subclasses.
  const CamoTokenSet();

  /// This set blended toward [other] at [t].
  T lerp(T other, double t);
}

/// A numbered color scale, as brands name them (`brand[600]`).
@immutable
class CamoColorScale {
  /// Creates a scale from its steps.
  const CamoColorScale(this._steps);

  final Map<int, Color> _steps;

  /// The color at [step]; throws if the scale has no such step.
  Color operator [](int step) =>
      _steps[step] ?? (throw ArgumentError('No step $step in this scale'));

  /// Blends the steps both scales have; a step only one scale has switches at the midpoint.
  static CamoColorScale lerp(CamoColorScale a, CamoColorScale b, double t) {
    final steps = {...a._steps.keys, ...b._steps.keys};
    return CamoColorScale({
      for (final step in steps)
        step: switch ((a._steps[step], b._steps[step])) {
          (final Color x, final Color y) => Color.lerp(x, y, t)!,
          (final x, final y) => t < 0.5 ? (x ?? y)! : (y ?? x)!,
        },
    });
  }

  @override
  bool operator ==(Object other) =>
      other is CamoColorScale && mapEquals(other._steps, _steps);

  @override
  int get hashCode =>
      Object.hashAll(_steps.entries.map((e) => Object.hash(e.key, e.value)));
}

/// A named dimension scale (`space['lg']`), in logical pixels.
@immutable
class CamoDimensionScale {
  /// Creates a scale from its steps.
  const CamoDimensionScale(this._steps);

  final Map<String, double> _steps;

  /// The size named [name]; throws if the scale has no such step.
  double operator [](String name) =>
      _steps[name] ?? (throw ArgumentError('No step "$name" in this scale'));

  @override
  bool operator ==(Object other) =>
      other is CamoDimensionScale && mapEquals(other._steps, _steps);

  @override
  int get hashCode =>
      Object.hashAll(_steps.entries.map((e) => Object.hash(e.key, e.value)));
}
